import heapq

def match(orders):
    trades = []

    # order book storage: id -> dict with side, price, qty, seq, cancelled
    book = {}

    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    seq_counter = 0

    def clean_buy_heap():
        while buy_heap:
            neg_price, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or info['cancelled'] or info['qty'] <= 0 or info['side'] != 'buy':
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or info['cancelled'] or info['qty'] <= 0 or info['side'] != 'sell':
                heapq.heappop(sell_heap)
            else:
                break

    def match_incoming(side, price, qty, incoming_id):
        # price is None for market orders (match any price)
        remaining = qty
        if side == 'buy':
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                top_price, top_seq, top_id = sell_heap[0]
                if price is not None and top_price > price:
                    break
                info = book[top_id]
                trade_qty = min(remaining, info['qty'])
                info['qty'] -= trade_qty
                remaining -= trade_qty
                trades.append([incoming_id, top_id, top_price, trade_qty])
                if info['qty'] <= 0:
                    heapq.heappop(sell_heap)
        else:  # side == 'sell'
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                if price is not None and top_price < price:
                    break
                info = book[top_id]
                trade_qty = min(remaining, info['qty'])
                info['qty'] -= trade_qty
                remaining -= trade_qty
                trades.append([top_id, incoming_id, top_price, trade_qty])
                if info['qty'] <= 0:
                    heapq.heappop(buy_heap)
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            if remaining > 0:
                book[oid] = {
                    'side': side,
                    'price': price,
                    'qty': remaining,
                    'cancelled': False
                }
                seq_counter += 1
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
            else:
                # fully filled, still record as known (filled) so cancel does nothing
                book[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'cancelled': False
                }
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            book[oid] = {
                'side': side,
                'price': price,
                'qty': 0,
                'cancelled': False
            }
        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, oid)
            book[oid] = {
                'side': side,
                'price': None,
                'qty': 0,
                'cancelled': False
            }
        elif typ == 'cancel':
            _, oid = order
            info = book.get(oid)
            if info is not None and not info['cancelled'] and info['qty'] > 0:
                info['cancelled'] = True
                info['qty'] = 0

    return trades

